 const arrow=(vx,vy,color)=>{const ex=x+vx,ey=y+vy,a=Math.atan2(vy,vx),q=.13;return g.line(x,y,ex,ey,color,false,2.5)+g.line(ex,ey,ex-q*Math.cos(a-.5),ey-q*Math.sin(a-.5),color,false,2.5)+g.line(ex,ey,ex-q*Math.cos(a+.5),ey-q*Math.sin(a+.5),color,false,2.5)};if(norm>0)g.add(arrow(gx*scale,gy*scale,C.green));g.add(arrow(dx*.8,dy*.8,C.blue));g.add(g.dot(x,y,C.orange));const h=.1,lin=f(x,y)+h*(gx*dx+gy*dy),exact=f(x+h*dx,y+h*dy);r=[`f = <strong>${fmt(f(x,y))}</strong>`,`∇f = <strong>(${fmt(gx)}; ${fmt(gy)})</strong>`,`Dᵤf = <strong>${fmt(gx*dx+gy*dy)}</strong>`,`Максимум Dᵤf = ${fmt(norm)}`,`При h=0,1: плоскость ${fmt(lin)}, точно ${fmt(exact)}`];legend=[['Градиент (направление)',C.green],['Единичное направление',C.blue],['Точка',C.orange]];
